\mathrm{df\text{-}robinson\text{-}arithmetic} \vdash
Q \coloneqq
\left\{
\begin{aligned}
&\forall x\;(S(x) \neq 0),\\
&\forall x\forall y\;(S(x) = S(y) \to x = y),\\
&\forall x\;(x + 0 = x),\\
&\forall x\forall y\;(x + S(y) = S(x + y)),\\
&\forall x\;(x \times 0 = 0),\\
&\forall x\forall y\;(x \times S(y) = x \times y + x),\\
&\forall x\;(x = 0 \lor \exists y\;(x = S(y)))
\end{aligned}
\right\}
